// Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
export const sensitiveInputInstruction =
  "Each placeholder listed in sensitiveInputPlaceholders is a usable reference to an input already supplied for this task. When the task needs that input, use the normal typing action with its exact placeholder. The host replaces the placeholder with the corresponding value immediately before typing into the application.";

// Purpose: the existing host-to-Kaijan binding lets a host that refuses direct
// sensitive-value passing hand the inputs to Kaijan. The agreed dummy-value
// adapter keeps normal computer typing; it is not a screenshot/privacy policy.
export function prepareBrowserInputs(parameters, sensitiveNames) {
  const names = new Set(sensitiveNames);
  const bindings = Object.entries(parameters)
    .filter(([name]) => names.has(name))
    .map(([name, value], index) => ({
      name,
      value: String(value),
      placeholder: "KAIJAN_INPUT" + (index + 1) + "_VALUE",
    }));
  const byName = new Map(
    bindings.map((binding) => [binding.name, binding.placeholder]),
  );
  return {
    parameters: Object.fromEntries(
      Object.entries(parameters).map(([name, value]) => [
        name,
        byName.get(name) ?? value,
      ]),
    ),
    placeholders: bindings.map(({ name, placeholder }) => ({
      name,
      placeholder,
    })),
    usedNames(text) {
      return bindings
        .filter((binding) => text.includes(binding.placeholder))
        .map((binding) => binding.name);
    },
    resolve(text) {
      if (!bindings.length) return text;
      // Match only the model's original text, so inserted values cannot trigger
      // another replacement if they happen to contain a different placeholder.
      const pattern = new RegExp(
        bindings.map((binding) => binding.placeholder).join("|"),
        "g",
      );
      const values = new Map(
        bindings.map((binding) => [binding.placeholder, binding.value]),
      );
      return text.replace(pattern, (placeholder) => values.get(placeholder));
    },
  };
}
